async function loadRows(ws,collection,key){const privateRows=SENSITIVE_COLLECTIONS.has(collection);const {data:userData,error:userError}=await supabase.auth.getUser();if(userError)throw userError;const user=userData?.user;if(!user)throw new Error("authentication-required");let request=privateRows?supabase.from("spiritual_private_records").select("id,data,encrypted_data,encryption_version,updated_at").eq("user_id",user.id):supabase.from("workspace_records").select("id,data,updated_at").eq("system_id","spiritual");request=request.eq("workspace_id",ws).eq("collection",collection).eq("deleted",false).order("updated_at",{ascending:false}).limit(500);const {data,error}=await request;if(privateRows&&!key)throw new Error("encryption-locked");if(error){if(!privateRows||!globalThis.navigator?.onLine)throw error;const cached=await readEncryptedSpiritualRecords({userId:user.id,workspaceId:ws,collection});return Promise.all(cached.map(async r=>({...await decryptSpiritualPayload(key,r.envelope),id:r.id,updatedAt:r.updatedAt,offlineCached:true})));}const records=[];for(const r of data||[]){let value;if(privateRows&&r.encrypted_data){value=await decryptSpiritualPayload(key,r.encrypted_data);}else{value=r.data||{};if(privateRows){const envelope=await encryptSpiritualPayload(key,value);const {error:upgradeError}=await supabase.from("spiritual_private_records").update({data:{},encrypted_data:envelope,encryption_version:1,updated_at:new Date().toISOString()}).eq("user_id",user.id).eq("workspace_id",ws).eq("id",r.id);if(upgradeError)throw upgradeError;}}records.push({...value,id:r.id,updatedAt:r.updated_at});}return records;}
